import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <type_traits>
using namespace cute;
template <typename T>
__global__ void max_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int outer, int reduce, int inner,
    int col_offset, int col_count)
{
    // Flattened grid-stride loop over (outer * col_count) output elements.
    // col_offset/col_count allow this kernel to process an arbitrary
    // sub-range of the inner (contiguous) dimension, which is used to
    // handle the tail columns that don't fit into a vectorized load.
    const int64_t total  = (int64_t)outer * (int64_t)col_count;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total;
         idx += stride) {
        const int64_t o  = idx / col_count;
        const int64_t ic = idx - o * col_count;
        const int64_t i0 = col_offset + ic;
        const T* __restrict__ p = X + o * (int64_t)reduce * (int64_t)inner + i0;
        // Use 4 independent accumulator chains to break the sequential
        // dependency of a single running max, exposing more memory-level
        // parallelism and hiding global memory latency along the reduce dim.
        T m0, m1, m2, m3;
        int r = 0;
        if (reduce >= 4) {
            m0 = p[0 * (int64_t)inner];
            m1 = p[1 * (int64_t)inner];
            m2 = p[2 * (int64_t)inner];
            m3 = p[3 * (int64_t)inner];
            p += 4 * (int64_t)inner;
            r = 4;
            #pragma unroll 4
            for (; r + 4 <= reduce; r += 4) {
                T v0 = p[0 * (int64_t)inner];
                T v1 = p[1 * (int64_t)inner];
                T v2 = p[2 * (int64_t)inner];
                T v3 = p[3 * (int64_t)inner];
                m0 = v0 > m0 ? v0 : m0;
                m1 = v1 > m1 ? v1 : m1;
                m2 = v2 > m2 ? v2 : m2;
                m3 = v3 > m3 ? v3 : m3;
                p += 4 * (int64_t)inner;
            }
        } else {
            m0 = p[0];
            m1 = m0; m2 = m0; m3 = m0;
            p += inner;
            r = 1;
        }
        T m = m0;
        m = m1 > m ? m1 : m;
        m = m2 > m ? m2 : m;
        m = m3 > m ? m3 : m;
        for (; r < reduce; ++r) {
            T v = *p;
            m = v > m ? v : m;
            p += inner;
        }
        Y[o * (int64_t)inner + i0] = m;
    }
}
// Vectorized specialization for float: each thread reduces 4 consecutive
// output columns at once using 16-byte (float4) loads. This reduces the
// number of load instructions issued per thread by 4x along the (very
// large) reduce dimension, which is where this memory-bound kernel
// spends essentially all of its time. Since `reduce` is a multiple of 4
// (4096) and float allocations are at least 16-byte aligned, the base
// offset for every (o, group) pair is guaranteed to be 16-byte aligned.
__global__ void max_reduce_kernel_vec4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer, int reduce, int inner, int inner_vec4)
{
    const int64_t total  = (int64_t)outer * (int64_t)inner_vec4;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total;
         idx += stride) {
        const int64_t o  = idx / inner_vec4;
        const int64_t g  = idx - o * inner_vec4;
        const int64_t i0 = g * 4;
        const float* __restrict__ p = X + o * (int64_t)reduce * (int64_t)inner + i0;
        float4 m = *reinterpret_cast<const float4*>(p);
        p += inner;
        #pragma unroll 4
        for (int r = 1; r < reduce; ++r) {
            float4 v = *reinterpret_cast<const float4*>(p);
            m.x = v.x > m.x ? v.x : m.x;
            m.y = v.y > m.y ? v.y : m.y;
            m.z = v.z > m.z ? v.z : m.z;
            m.w = v.w > m.w ? v.w : m.w;
            p += inner;
        }
        float4* outp = reinterpret_cast<float4*>(Y + o * (int64_t)inner + i0);
        *outp = m;
    }
}
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto x_c = x.contiguous();
    int64_t outer = 1;
    for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
    int64_t reduce = x_c.size(dim);
    int64_t inner = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);
    std::vector<int64_t> out_sizes;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dim) out_sizes.push_back(x_c.size(d));
    }
    auto y = torch::empty(out_sizes, x_c.options());
    const int Threads = 256;
    const int64_t max_blocks = 65535;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    AT_DISPATCH_FLOATING_TYPES_AND2(at::kHalf, at::kBFloat16, x_c.scalar_type(), "max_reduce_kernel", ([&] {
        if constexpr (std::is_same<scalar_t, float>::value) {
            bool ptrs_aligned =
                (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
                (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
            bool inner_divisible_by_4 = (inner % 4 == 0);
            int64_t inner_vec4 = inner / 4;
            int64_t tail_offset = inner_vec4 * 4;
            int64_t tail_count = inner - tail_offset;
            if (ptrs_aligned && inner_divisible_by_4 && inner_vec4 > 0) {
                int64_t total_vec = outer * inner_vec4;
                int64_t num_blocks = (total_vec + Threads - 1) / Threads;
                if (num_blocks > max_blocks) num_blocks = max_blocks;
                if (num_blocks < 1) num_blocks = 1;
                max_reduce_kernel_vec4<<<(unsigned)num_blocks, Threads, 0, stream>>>(
                    x_c.data_ptr<float>(),
                    y.data_ptr<float>(),
                    (int)outer, (int)reduce, (int)inner, (int)inner_vec4
                );
                if (tail_count > 0) {
                    int64_t total_tail = outer * tail_count;
                    int64_t num_blocks_tail = (total_tail + Threads - 1) / Threads;
                    if (num_blocks_tail > max_blocks) num_blocks_tail = max_blocks;
                    if (num_blocks_tail < 1) num_blocks_tail = 1;
                    max_reduce_kernel<float><<<(unsigned)num_blocks_tail, Threads, 0, stream>>>(
                        x_c.data_ptr<float>(),
                        y.data_ptr<float>(),
                        (int)outer, (int)reduce, (int)inner,
                        (int)tail_offset, (int)tail_count
                    );
                }
            } else {
                int64_t total_elems = outer * inner;
                int64_t num_blocks = (total_elems + Threads - 1) / Threads;
                if (num_blocks > max_blocks) num_blocks = max_blocks;
                if (num_blocks < 1) num_blocks = 1;
                max_reduce_kernel<float><<<(unsigned)num_blocks, Threads, 0, stream>>>(
                    x_c.data_ptr<float>(),
                    y.data_ptr<float>(),
                    (int)outer, (int)reduce, (int)inner,
                    0, (int)inner
                );
            }
        } else {
            int64_t total_elems = outer * inner;
            int64_t num_blocks = (total_elems + Threads - 1) / Threads;
            if (num_blocks > max_blocks) num_blocks = max_blocks;
            if (num_blocks < 1) num_blocks = 1;
            max_reduce_kernel<scalar_t><<<(unsigned)num_blocks, Threads, 0, stream>>>(
                x_c.data_ptr<scalar_t>(),
                y.data_ptr<scalar_t>(),
                (int)outer, (int)reduce, (int)inner,
                0, (int)inner
            );
        }
    }));
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "max_reduce_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom CUDA/CUTE kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_forward(x, self.dim)

